/**
 * @event
 * @name scwin.grd_EduScheduleList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_EduScheduleList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_EduScheduleList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_EduScheduleList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.modify === 'function') { scwin.modify(r["disclsEduApplSeq"], r["disclsEduApctTpCd"], r["disclsEduCrsNm"], r["disclsEduStrtDd"], r["disclsEduEndDd"], r["disclsEduAcptStrtDd"], r["disclsEduAcptEndDd"], r["disclsEduEvtItmExpYn"], r["partcPersInputYn"]); } else { console.error('[sdd] 행 동작 미정의: scwin.modify (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.modify'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_EduScheduleList.oncellclick' });
    }
};


